import{_ as a}from"./chunks/1_resource_20191117164149.CNrfBleH.js";import{_ as i,o as e,c as t,a0 as r}from"./chunks/framework.DqMqoJl9.js";const m=JSON.parse('{"title":"资源合并与压缩","description":"","frontmatter":{},"headers":[],"relativePath":"performance/old/1_resource.md","filePath":"performance/old/1_resource.md","lastUpdated":1791573371000}'),s={name:"performance/old/1_resource.md"};function o(p,l,h,n,c,_){return e(),t("div",null,[...l[0]||(l[0]=[r('<h1 id="资源合并与压缩" tabindex="-1">资源合并与压缩 <a class="header-anchor" href="#资源合并与压缩" aria-label="Permalink to &quot;资源合并与压缩&quot;">​</a></h1><h2 id="_1-优化思路" tabindex="-1">1 优化思路 <a class="header-anchor" href="#_1-优化思路" aria-label="Permalink to &quot;1 优化思路&quot;">​</a></h2><p>web 前端是 BS 架构。</p><p>BS 架构就是，前端代码开发完成后，将代码发布到远程服务器。然后用户通过浏览器输入网址，这时浏览器向远程服务器发出请求，动态的加载页面的资源。</p><p>因此 web 前端的访问过程是一个动态、增量的加载资源的过程。如果浏览器能越快的获取资源，那么用户就能越快的看到页面，体验也就越好。这是前端性能优化很重要的一个点。</p><p>从资源加载方面优化，需要先分析一下，浏览器的一个请求从发送到返回都经历了什么？</p><p><img src="'+a+'" alt=""></p><p>上图是一个 http 请求发出到响应的过程，在这个过程中可以去挖掘一些可以优化的点，去实现前端的性能优化。</p><p>请求过程中一些潜在的性能优化点：</p><ul><li>dns 是否可以通过缓存减少 dns 查询时间</li><li>网络请求的过程中是否可以走最近的网络环境</li><li>相同的静态资源是否可以缓存</li><li>能否减少 http 请求大小</li><li>减少 http 请求</li><li>服务端渲染</li></ul><h2 id="_2-优化点" tabindex="-1">2 优化点 <a class="header-anchor" href="#_2-优化点" aria-label="Permalink to &quot;2 优化点&quot;">​</a></h2><p>资源合并与压缩涉及到的优化点主要有两个，一个是减少 http 请求数量，另外是减少请求资源的大小</p><p>具体的优化点如下：</p><ul><li>html 压缩</li><li>css 压缩</li><li>js 的压缩和混乱</li><li>文件合并</li><li>开启 gzip</li></ul><h2 id="_3-html-压缩" tabindex="-1">3 html 压缩 <a class="header-anchor" href="#_3-html-压缩" aria-label="Permalink to &quot;3 html 压缩&quot;">​</a></h2><p>html 代码压缩就是压缩这些在文本文件中有意义，但是在 html 中不显示的字符，包括空格、制表符、换行符等，还有一些其他无意义的字符，如 html 注释也可以被压缩</p><h2 id="_4-css-压缩" tabindex="-1">4 css 压缩 <a class="header-anchor" href="#_4-css-压缩" aria-label="Permalink to &quot;4 css 压缩&quot;">​</a></h2><ul><li>无效代码删除（空格、换行、注释等）</li><li>css 语义合并（重复的代码）</li></ul><h2 id="_5-js-压缩与混乱" tabindex="-1">5 js 压缩与混乱 <a class="header-anchor" href="#_5-js-压缩与混乱" aria-label="Permalink to &quot;5 js 压缩与混乱&quot;">​</a></h2><ul><li>无效字符的删除</li><li>删除注释</li><li>代码语义的缩减和优化（缩短变量名的长度，删除重复代码等）</li><li>代码保护（js 的代码是透明的，压缩和混淆后可以降低代码的可读性）</li></ul><p>js 和 css 代码压缩不仅能减少文件大小，还有有网站安全方面的收益。并且 js 和 css 的压缩率是比较高的，可以很大程度的减少文件的大小</p><h2 id="_6-文件合并" tabindex="-1">6 文件合并 <a class="header-anchor" href="#_6-文件合并" aria-label="Permalink to &quot;6 文件合并&quot;">​</a></h2><p>合并文件可以减少 http 请求的数量。</p><p>请求多个 js 文件跟请求一个 js 文件相比：</p><ul><li>文件与文件之间有插入的上行请求，增加了 N-1 个网络延迟</li><li>受丢包的影响更严重（请求数量更多，丢包的概率更大）</li></ul><p>当然合并文件也不是万能的，合并文件也有它的缺点：</p><ul><li>首屏渲染问题</li><li>缓存失效问题</li></ul><p>文件合并后自然单个文件会变得更大。如果网站是单页面应用，合并文件通常会把公共库还有其他页面的 js 都打包在一起，而首屏渲染需要等待这些资源都加载完成。其中很多资源是首屏页面不需要的。</p><p>缓存失效问题，合并文件会造成大面积的缓存失效。通常当一个文件有改动时才需要重新加载。如果将几个文件合并的话，其中一个文件有改动，那么合并后的文件也会改动，这时就需要重新加载整个文件。而未合并的话只需要重新加载改动的文件就行。</p><p><strong>常用的文件合并策略：</strong></p><ul><li>公共库合并（通常公共库会很少改动，将它们合并更不容易出现缓存失效问题）</li><li>分页面合并（也就是按需加载，不要将所有页面都打包到一起，而是将单个页面所依赖的资源打包，匹配到某个路由的时候只加载这个路由需要的资源）</li></ul>',31)])])}const f=i(s,[["render",o]]);export{m as __pageData,f as default};
